    for (int index = 1;; ++index) {
        char key[32];
        std::snprintf(key, sizeof(key), "Slot %d", index);
        const ScenePropertyBlock* sub = scene_deck_sub_block(bag, key);
        if (sub == nullptr) break;
        bsp::AirOpsSceneSlot row;
        row.type = scene_deck_type(*sub, library);
