    record.member_names.clear();
    record.member_spawn_index.clear();
    record.member_units.clear();

    std::size_t queued = 0;
    for (std::size_t wing = 0; wing < plan.members.size(); ++wing) {
        const bsp::PlaneSquadronMemberPlan& member = plan.members[wing];
        if (wing == 0) {
