                        if (seg && own) ++own_both;
                        else if (seg) ++own_seg_only;
                        else if (own) ++own_height_only;
                        if (seg) ++seg_land;
                        if (high) ++height_land;
                        if (seg && high) {
                            ++both;
                            const double d = std::fabs(static_cast<double>(hit.point[1]) - ground);
                            sum += d;
                            worst = std::max(worst, d);
